SELECT "line_charge_detail_id"
  FROM "line_charge_details"
 WHERE "line_charge_id"         = #{lineChargeId}
   AND "rosen_bus_stop_id_from" = #{fromId}
   AND "rosen_bus_stop_id_to"   = #{toId}
   AND "del_flag"             = 0

mapper.update:
UPDATE "line_charge_details"
   SET "line_charge"           = #{entity.lineCharge}
     , "ic_price"              = #{entity.icPrice}
     , "updated_user"          = #{session.userId}
     , "updated_at"            = CURRENT_TIMESTAMP
WHERE "del_flag" = 0
  AND "line_charge_id"         = #{entity.lineChargeId}
  AND "rosen_bus_stop_id_from" = #{entity.rosenBusStopIdFrom}
  AND "rosen_bus_stop_id_to"   = #{entity.rosenBusStopIdTo}
